package ug.audiocity.studio;
import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
public class ProTests {
 static int passed;static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);passed++;}
 static float[] constant(int frames,float l,float r){float[] out=new float[frames*2];for(int i=0;i<frames;i++){out[2*i]=l;out[2*i+1]=r;}return out;}
 public static void main(String[] args)throws Exception {
  check(Math.abs(Core.faderGain(60.0/66)-1)<1e-10,"Logarithmic fader has a precise 0 dB point");
  check(Core.faderGain(0)==0&&Math.abs(20*Math.log10(Core.faderGain(1))-6)<1e-8,"Fader reaches silence and +6 dB");
  boolean inverse=true;for(double p=.05;p<1;p+=.05)inverse&=Math.abs(Core.faderPosition(Core.faderGain(p))-p)<1e-9;check(inverse,"Fader inverse is stable over its range");
  check(Core.snap(12345,100,0)==12345,"Free placement does not quantise samples");
  check(Core.snap(21000,100,1)==28800&&Core.snap(21000,100,4)==21600,"Quarter and sixteenth grids differ correctly");
  check(Core.snap(33333,93,8)==34839,"Snap preserves fractional grid timing without accumulating rounded-step errors");
  Core.Session faded=StudioTests.session(constant(4000,.1f,.1f));Core.Clip c=faded.tracks.get(0).clips.get(0);c.gain=2;c.fadeIn=1000;c.fadeOut=800;float[] fade=StudioTests.render(faded,4000);
  check(Math.abs(fade[0])<1e-8&&Math.abs(fade[7998])<1e-8,"Fade edges reach zero");check(Math.abs(fade[3000]-.2)<1e-6,"Clip gain is applied before channel processing");
  Core.Session split=faded.copy();Core.Clip left=split.tracks.get(0).clips.get(0),right=left.copy();left.length=2000;right.start=2000;right.offset=2000;right.envelopeOffset=2000;right.length=2000;split.tracks.get(0).clips.add(right);float[] splitAudio=StudioTests.render(split,4000);double maxDiff=0;for(int i=0;i<fade.length;i++)maxDiff=Math.max(maxDiff,Math.abs(fade[i]-splitAudio[i]));check(maxDiff<1e-7,"Splitting preserves existing fades sample for sample");
  Core.Session compressed=StudioTests.session(StudioTests.wave(Core.RATE,400,.4));Core.Track track=compressed.tracks.get(0);track.fx=Core.preset(1);track.fx.threshold=-30;float[] processed=StudioTests.render(compressed,Core.RATE);check(track.reduction>6,"Live compression reduction is measured from DSP gain");track.bypassFx=true;float[] bypassed=StudioTests.render(compressed,Core.RATE);check(StudioTests.rms(bypassed,24000,40000)>StudioTests.rms(processed,24000,40000)*2,"Channel FX bypass restores dry signal");
  Core.Session stereo=StudioTests.session(constant(1024,.1f,.2f));stereo.tracks.get(0).pan=0;Core.Renderer renderer=new Core.Renderer(stereo);float[] block=new float[2048];renderer.render(0,1024,block,false);Core.Track channel=stereo.tracks.get(0);check(Math.abs(channel.meterR/channel.meterL-2)<1e-6&&channel.peakHold==channel.meterR,"Stereo track metering and peak hold use distinct channels");check(Math.abs(renderer.peakRight/renderer.peakLeft-2)<1e-6,"Master meters have distinct channel levels");
  Core.Session hot=StudioTests.session(constant(1024,4,4));Core.Renderer limiter=new Core.Renderer(hot);limiter.render(0,512,block,false);check(limiter.overloaded&&limiter.limiterDb>0,"Master reports pre-limiter overload and gain reduction");hot.tracks.get(0).mute=true;limiter.render(512,512,block,false);check(!limiter.overloaded,"Overload event can clear on later silent blocks");
  Core.Biquad eq=new Core.Biquad();eq.set(0,120,6);Core.Session eqSession=StudioTests.session(StudioTests.wave(Core.RATE,60,.05));double dry=StudioTests.rms(StudioTests.render(eqSession,Core.RATE),24000,40000);eqSession.tracks.get(0).fx.low=6;double wet=StudioTests.rms(StudioTests.render(eqSession,Core.RATE),24000,40000);check(Math.abs(eq.db(60)-20*Math.log10(wet/dry))<.05,"EQ graph formula agrees with measured DSP response");
  Core.Fx first=Core.preset(1),second=Core.preset(1);first.high=-12;check(second.high==2,"Preset instances do not share mutable state");
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();Core.Session export=StudioTests.session(StudioTests.wave(4800,440,.2));export.tracks.get(0).pan=0;AudioIO.wav(bytes,export,24);byte[] wav=bytes.toByteArray();ByteBuffer header=ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);check(header.getShort(34)==24&&header.getShort(32)==6&&header.getInt(28)==288000,"24-bit WAV header uses stereo 6-byte frames");check(wav.length==44+(4800+Core.RATE*3)*6&&header.getInt(40)==wav.length-44,"24-bit WAV data length is correct");
  int count=0;boolean finite=true;for(int i=44;i<44+4800*6;i+=3){int value=(wav[i]&255)|((wav[i+1]&255)<<8)|(wav[i+2]<<16);finite&=Math.abs(value)<=7480000;if(value!=0)count++;}check(finite&&count>9000,"24-bit PCM contains signed non-silent samples within output ceiling");
  try(FileOutputStream output=new FileOutputStream(args.length>0?args[0]:"test-mix24.wav")){output.write(wav);}
  File dir=Files.createTempDirectory("studio-pro-compat").toFile();Core.Session s=new Core.Session();s.directory=dir.getPath();s.snapDivision=8;s.master=Core.faderGain(1);Core.Track t=new Core.Track("Vocals",0);t.volume=Core.faderGain(1);t.bypassFx=true;Core.Clip clip=AudioIO.store(dir,constant(2000,.1f,.1f),"Take",0);clip.gain=.5;clip.fadeIn=100;clip.fadeOut=200;t.clips.add(clip);s.tracks.add(t);AudioIO.save(s);Core.Session loaded=AudioIO.load(dir);Core.Clip loadedClip=loaded.tracks.get(0).clips.get(0);check(loaded.snapDivision==8&&loaded.tracks.get(0).bypassFx&&Math.abs(loaded.master-s.master)<1e-9&&Math.abs(loaded.tracks.get(0).volume-t.volume)<1e-9,"Snap, bypass and +6 dB faders persist");check(loadedClip.gain==.5&&loadedClip.fadeIn==100&&loadedClip.fadeOut==200,"Clip gain and fades persist");
  JSONObject json=new JSONObject(new String(Files.readAllBytes(new File(dir,"session.json").toPath()),"UTF-8"));json.remove("snapDivision");JSONObject jt=json.getJSONArray("tracks").getJSONObject(0);jt.remove("bypassFx");JSONObject jc=jt.getJSONArray("clips").getJSONObject(0);for(String key:new String[]{"gain","fadeIn","fadeOut","envelopeOffset","envelopeLength"})jc.remove(key);Files.write(new File(dir,"session.json").toPath(),json.toString().getBytes("UTF-8"));Core.Session legacy=AudioIO.load(dir);Core.Clip legacyClip=legacy.tracks.get(0).clips.get(0);check(legacy.snapDivision==4&&!legacy.tracks.get(0).bypassFx&&legacyClip.gain==1&&legacyClip.fadeIn==0&&legacyClip.fadeOut==0,"Version 0.1 session metadata receives compatible defaults");
  jc.put("envelopeOffset",2000).put("envelopeLength",2000);Files.write(new File(dir,"session.json").toPath(),json.toString().getBytes("UTF-8"));boolean refused=false;try{AudioIO.load(dir);}catch(IOException e){refused=true;}check(refused,"Invalid persisted envelope range is rejected");
  System.out.println(passed+" professional-workflow audio and compatibility checks passed.");
 }
}
